public class MembershipAccess { static String access(String m,String c){if(m.equals("public"))return "ALLOWED";if(m.equals("private"))return c.equals("SAME_CLASS")?"ALLOWED":"DENIED";if(m.equals("default"))return c.equals("SAME_CLASS")||c.equals("SAME_PACKAGE")?"ALLOWED":"DENIED";return c.equals("SAME_CLASS")||c.equals("SAME_PACKAGE")?"ALLOWED":"DENIED";} static String summarize(String[][]a){int y=0,n=0;for(String[]x:a)if(access(x[0],x[1]).equals("ALLOWED"))y++;else n++;return "Allowed: "+y+" | Denied: "+n;} public static void main(String[]x){System.out.println(access("private","SAME_CLASS"));}}
